/// <summary>
/// AVA
/// </summary>
/// <param name = "_contract">AVACorrectTraverseContract</param>
public void process(AVACorrectTraverseContract _contract)
{
    #OCCRetryCount

    try
    {
        this.setClosed(_contract);
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private void setClosed(AVACorrectTraverseContract _contract)
{
    AVATraverseTrans    travTrans;
    AVATraverseNum      travNum = _contract.parmTraverseNum();

    select firstonly travTrans where travTrans.TravNum == travNum
        && travTrans.TravStatus != AVATravStatus::Closed;
    if (travTrans)
    {
        warning("@NDX:NXATravStatusWarning2");
        return;
    }


    while select forupdate travTrans where travTrans.TravNum == travNum
                                        && travTrans.TravStatus == AVATravStatus::Closed
    {
        ttsbegin;
        travTrans.TravStatus = AVATravStatus::InProcess;
        travTrans.update();
        ttscommit;
    }
}
